// Normalize Inputs from Form Submission, Webhook, or Canvas Manual Trigger
const item = $input.first()?.json || {};
const body = item.body || {};
const query = item.query || {};

// Support Form Trigger labels, field IDs, Webhook body, query params, or fallback
const focusTopic = item['Focus Topic'] || item['field-0'] || item.focus_topic || body['Focus Topic'] || body.focus_topic || body.topic || query.focus_topic || 'Hawaii business & AI automation';
const targetAudience = item['Target Audience'] || item['field-1'] || item.target_audience || body['Target Audience'] || body.target_audience || body.audience || query.target_audience || 'Local business owners, entrepreneurs, and service professionals';
const additionalContext = item['Additional Context'] || item['field-2'] || item['field-3'] || item.additional_context || body['Additional Context'] || body.additional_context || query.additional_context || 'Focus on practical ROI, eliminating repetitive manual admin work, and modernizing traditional workflows';

const agentId = item.agentId || body.agentId || query.agentId || 'cmtry4o2s0001bnqo9unud2s2';
const taskId = item.taskId || body.taskId || query.taskId || '';
const runId = item.runId || body.runId || query.runId || '';

// Detect whether triggered via Form Submission or Webhook
const isForm = Boolean(item.submittedAt || item['Focus Topic'] || item['field-0']);
const isWebhook = Boolean(item.headers || item.body || item.query);

return [{
  json: {
    focus_topic: focusTopic,
    target_audience: targetAudience,
    additional_context: additionalContext,
    agent_id: agentId,
    task_id: taskId,
    run_id: runId,
    is_form: isForm,
    is_webhook: isWebhook,
    llm_provider: 'Ollama Local',
    ollama_url: 'http://host.docker.internal:11434/api/chat',
    ollama_model: 'qwen3.6:35b'
  }
}];

// Parse YouTube HTML and Extract Real Post Metadata
const items = $input.all();
const html = items[0]?.json?.data || items[0]?.json || '';
const rawHtml = typeof html === 'string' ? html : JSON.stringify(html);

// Carry forward focus topic from upstream
const focusTopic = items[0]?.json?.focus_topic || $('Research Config & Parameters').first()?.json?.focus_topic || 'Hawaii business & AI automation';

const match = rawHtml.match(/var ytInitialData = ({[\s\S]*?});<\/script>/);
const videos = [];

if (match) {
  try {
    const json = JSON.parse(match[1]);

    function walk(obj) {
      if (!obj || typeof obj !== 'object') return;

      if (obj.videoRenderer) {
        const vr = obj.videoRenderer;
        const title = vr.title?.runs?.[0]?.text || vr.title?.simpleText || '';
        const views = vr.viewCountText?.simpleText || vr.viewCountText?.runs?.[0]?.text || '';
        const published = vr.publishedTimeText?.simpleText || '';
        const channel = vr.ownerText?.runs?.[0]?.text || '';
        const videoId = vr.videoId || '';
        const length = vr.lengthText?.simpleText || '';
        const snippet = vr.detailedMetadataSnippets?.[0]?.snippetText?.runs?.map(r => r.text).join('') || '';

        if (title && videoId) {
          videos.push({
            platform: 'YouTube',
            type: 'Video',
            title: title,
            views: views,
            published: published,
            channel: channel,
            duration: length,
            url: 'https://www.youtube.com/watch?v=' + videoId,
            snippet: snippet
          });
        }
      }

      if (obj.reelItemRenderer) {
        const rr = obj.reelItemRenderer;
        const title = rr.headline?.simpleText || '';
        const views = rr.viewCountText?.simpleText || '';
        const channel = rr.ownerText?.runs?.[0]?.text || '';
        const videoId = rr.videoId || '';

        if (title && videoId) {
          videos.push({
            platform: 'YouTube Shorts',
            type: 'Short',
            title: title,
            views: views,
            channel: channel,
            url: 'https://www.youtube.com/shorts/' + videoId
          });
        }
      }

      for (const k of Object.keys(obj)) {
        walk(obj[k]);
      }
    }

    walk(json);
  } catch (e) {}
}

return [{
  json: {
    focus_topic: focusTopic,
    scraped_videos_count: videos.length,
    scraped_videos: videos.slice(0, 15)
  }
}];

// Parse Google News / Search RSS
const items = $input.all();
const xml = items[0]?.json?.data || items[0]?.json || '';
const rawXml = typeof xml === 'string' ? xml : JSON.stringify(xml);

const trends = [];
const regex = /<item>[\s\S]*?<title>([\s\S]*?)<\/title>[\s\S]*?<link>([\s\S]*?)<\/link>[\s\S]*?<pubDate>([\s\S]*?)<\/pubDate>[\s\S]*?<\/item>/g;
let m;

while ((m = regex.exec(rawXml)) !== null) {
  const rawTitle = m[1].replace(/<!\[CDATA\[(.*?)\]\]>/g, '$1').trim();
  const link = m[2].trim();
  const pubDate = m[3].trim();

  const parts = rawTitle.split(' - ');
  const title = parts.slice(0, -1).join(' - ') || rawTitle;
  const source = parts.length > 1 ? parts[parts.length - 1] : 'News Source';

  if (title) {
    trends.push({
      platform: 'Google Search & News',
      headline: title,
      source: source,
      published: pubDate,
      url: link
    });
  }
}

return [{
  json: {
    scraped_trends_count: trends.length,
    scraped_trends: trends.slice(0, 15)
  }
}];

// Merge Scraped Social Posts & Live Search Trends
const ytData = $('Parse YouTube Metadata').first()?.json || {};
const newsData = $('Parse Search Trends').first()?.json || {};
const configData = $('Research Config & Parameters').first()?.json || {};

const scrapedVideos = ytData.scraped_videos || [];
const scrapedTrends = newsData.scraped_trends || [];

const focusTopic = configData.focus_topic || 'Hawaii business & AI automation';
const targetAudience = configData.target_audience || 'Local business owners and entrepreneurs';
const additionalContext = configData.additional_context || 'Focus on practical automation and ROI';
const isWebhook = configData.is_webhook === true;

return [{
  json: {
    focus_topic: focusTopic,
    target_audience: targetAudience,
    additional_context: additionalContext,
    is_webhook: isWebhook,
    live_scraped_data: {
      total_videos_found: scrapedVideos.length,
      videos: scrapedVideos,
      total_trends_found: scrapedTrends.length,
      trends: scrapedTrends
    }
  }
}];

