    "Write the complete, publication-grade, human-readable MARKDOWN report directly (do NOT wrap in JSON)."
  ].join("\n");

  if (isOllama) {
    return {
      model: model,
      messages: [
        { role: "system", content: sysText },
        { role: "user", content: userText }
