// Extract & Format Social Media Research Markdown Report
const items = $input.all();
const run = items[0]?.json || {};

// 1. Extract raw text from Ollama response
let rawText = '';
if (run?.message?.content) {
  rawText = run.message.content;
} else if (run?.response) {
  rawText = run.response;
} else if (run?.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = run.candidates[0].content.parts[0].text;
} else if (typeof run.output === 'string') {
  rawText = run.output;
} else if (run.text) {
  rawText = run.text;
}

// Strip thinking tags if generated by reasoning models
rawText = rawText.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// Strip outer markdown code fences if wrapped in ```markdown ... ```
let markdown = rawText;
const fenceMatch = rawText.match(/^\`\`\`(?:markdown)?\s*([\s\S]*?)\s*\`\`\`$/i);
if (fenceMatch) {
  markdown = fenceMatch[1].trim();
}

// 2. Clean emojis and mojibake symbols
markdown = markdown
  .replace(/[\u{1F300}-\u{1F9FF}]/gu, '')
  .replace(/[\u{1F600}-\u{1F64F}]/gu, '')
  .replace(/[\u{1F680}-\u{1F6FF}]/gu, '')
  .replace(/[\u{2600}-\u{26FF}]/gu, '')
  .replace(/[\u{2700}-\u{27BF}]/gu, '')
  .replace(/ðŸ[^\s]*/g, '')
  .replace(/\r\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n');

// 3. Ensure clean title header if missing
if (!markdown.startsWith('#')) {
  markdown = '# Social Media Market Research & Viral Trends Report\n\n' + markdown;
}

// 4. Fetch context metadata
const mergedContext = $('Merge Live Research Data').first()?.json || {};
const normData = $('Normalize Inputs').first()?.json || {};
const focusTopic = mergedContext.focus_topic || 'Hawaii business & AI automation';
const targetAudience = mergedContext.target_audience || 'Local business owners and entrepreneurs';
const isWebhook = mergedContext.is_webhook === true;
const liveData = mergedContext.live_scraped_data || {};
const scrapedVideos = liveData.videos || [];
const scrapedTrends = liveData.trends || [];

const agentId = normData.agent_id || 'cmtry4o2s0001bnqo9unud2s2';
const taskId = normData.task_id || '';
const runId = normData.run_id || '';

const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
const fileSlug = 'social-media-research-' + timestamp;

return [{
  json: {
    success: true,
    file_slug: fileSlug,
    focus_topic: focusTopic,
    target_audience: targetAudience,
    agent_id: agentId,
    task_id: taskId,
    run_id: runId,
    is_webhook: isWebhook,
    live_videos_count: scrapedVideos.length,
    live_trends_count: scrapedTrends.length,
    markdown: markdown,
    report: markdown
  }
}];
